.quiz-progress {
  display: flex;
  gap: 6px;
  margin-bottom: 28px;
}

.quiz-progress__segment {
  flex: 1;
  height: 4px;
  border-radius: 99px;
  background: var(--color-border);
  transition: background var(--transition);
}

.quiz-progress__segment--active {
  background: var(--color-primary);
}

