.checkbox-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 4px;
}

.checkbox-option {
  position: relative;
}

.checkbox-option input[type="checkbox"] {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
  pointer-events: none;
}

.checkbox-option__label {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border: 1.5px solid var(--color-check-border);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: border-color var(--transition), background var(--transition), box-shadow var(--transition);
  user-select: none;
  font-size: 14px;
  color: var(--color-text);
  line-height: 1.4;
}

.checkbox-option__label:hover {
  border-color: var(--color-primary);
  background: #f5f6ff;
}

.checkbox-option input[type="checkbox"]:focus-visible + .checkbox-option__label {
  outline: 3px solid var(--color-primary);
  outline-offset: 2px;
}

.checkbox-option input[type="checkbox"]:checked + .checkbox-option__label {
  border-color: var(--color-primary);
  background: #f0f1fe;
  color: var(--color-text);
}

/* Custom checkbox box */
.checkbox-option__box {
  flex-shrink: 0;
  width: 18px;
  height: 18px;
  border: 2px solid var(--color-check-border);
  border-radius: 5px;
  background: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: border-color var(--transition), background var(--transition);
}

.checkbox-option input[type="checkbox"]:checked + .checkbox-option__label .checkbox-option__box {
  border-color: var(--color-primary);
  background: var(--color-primary);
}

.checkbox-option__checkmark {
  display: none;
}

.checkbox-option input[type="checkbox"]:checked + .checkbox-option__label .checkbox-option__checkmark {
  display: block;
}

/* ── Submit area ── */
.quiz-footer {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-top: 8px;
}

.btn-submit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background: var(--color-primary);
  color: #fff;
  font-size: 15px;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-md);
  padding: 13px 28px;
  cursor: pointer;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
  box-shadow: 0 2px 8px rgba(91,106,240,0.25);
  width: 100%;
}

.btn-submit:hover {
  background: var(--color-primary-hover);
  box-shadow: 0 4px 14px rgba(91,106,240,0.35);
}

.btn-submit:active {
  background: var(--color-primary-active);
  transform: translateY(1px);
}

.btn-submit:focus-visible {
  outline: 3px solid var(--color-primary);
  outline-offset: 3px;
}

/* ── Result banner ── */
.quiz-result {
  display: none;
  align-items: flex-start;
  gap: 12px;
  padding: 16px 18px;
  border-radius: var(--radius-md);
  border: 1.5px solid;
  font-size: 14px;
  line-height: 1.5;
  animation: fadeSlideIn 300ms ease both;
}

.quiz-result--visible {
  display: flex;
}

.quiz-result--success {
  background: var(--color-success-bg);
  border-color: var(--color-success-border);
  color: var(--color-success-text);
}

.quiz-result--error {
  background: var(--color-error-bg);
  border-color: var(--color-error-border);
  color: var(--color-error-text);
}

.quiz-result__icon {
  flex-shrink: 0;
  margin-top: 1px;
}

.quiz-result__title {
  font-weight: 700;
  margin-bottom: 2px;
}

/* ── Validation state on options ── */
.checkbox-option--correct input[type="checkbox"]:checked + .checkbox-option__label {
  border-color: var(--color-success-border);
  background: var(--color-success-bg);
  color: var(--color-success-text);
}

.checkbox-option--correct input[type="checkbox"]:checked + .checkbox-option__label .checkbox-option__box {
  border-color: #34d399;
  background: #34d399;
}

.checkbox-option--wrong input[type="checkbox"]:checked + .checkbox-option__label {
  border-color: var(--color-error-border);
  background: var(--color-error-bg);
  color: var(--color-error-text);
}

.checkbox-option--wrong input[type="checkbox"]:checked + .checkbox-option__label .checkbox-option__box {
  border-color: #f87171;
  background: #f87171;
