  "use strict";

  // Question definitions — correctAnswers uses option values
  const questions = [
    {
      id: "q1",
      number: "Question 1 of 3",
      text: "Which of the following are statically typed programming languages?",
      help: "A statically typed language performs type checking at compile time rather than at runtime.",
      options: [
        { value: "java",       label: "Java" },
        { value: "python",     label: "Python" },
        { value: "typescript", label: "TypeScript" },
        { value: "rust",       label: "Rust" },
      ],
      correctAnswers: ["java", "typescript", "rust"],
    },
    {
      id: "q2",
      number: "Question 2 of 3",
      text: "Which of the following languages were originally designed for web front-end development?",
      help: null,
      options: [
        { value: "javascript", label: "JavaScript" },
        { value: "css",        label: "CSS" },
        { value: "go",         label: "Go" },
        { value: "coffeescript", label: "CoffeeScript" },
      ],
      correctAnswers: ["javascript", "css", "coffeescript"],
    },
    {
      id: "q3",
      number: "Question 3 of 3",
      text: "Which languages support first-class functions (functions as values)?",
      help: null,
      options: [
        { value: "haskell",    label: "Haskell" },
        { value: "javascript", label: "JavaScript" },
        { value: "c",          label: "C (ANSI C89)" },
        { value: "python",     label: "Python" },
      ],
      correctAnswers: ["haskell", "javascript", "python"],
    },
  ];

  function getChecked(questionId) {
    return Array.from(
      document.querySelectorAll(`input[name="${questionId}"]:checked`)
    ).map((el) => el.value);
  }

  function arraysMatch(a, b) {
    return a.length === b.length && [...a].sort().join() === [...b].sort().join();
  }

  function handleSubmit(e) {
    e.preventDefault();

    const form = document.getElementById("quiz-form");
    form.classList.add("quiz-submitted");

    let correctCount = 0;

    questions.forEach((q) => {
      const selected = getChecked(q.id);
      const isFullyCorrect = arraysMatch(selected, q.correctAnswers);
      if (isFullyCorrect) correctCount++;

      selected.forEach((val) => {
        const input = document.querySelector(
          `input[name="${q.id}"][value="${val}"]`
        );
        if (!input) return;
        const wrapper = input.closest(".checkbox-option");
        if (q.correctAnswers.includes(val)) {
          wrapper.classList.add("checkbox-option--correct");
        } else {
          wrapper.classList.add("checkbox-option--wrong");
        }
      });

      // Update progress segment colour
      const segment = document.getElementById(`progress-${q.id}`);
      if (segment) {
        segment.style.background = isFullyCorrect ? "#34d399" : "#f87171";
      }
    });

    // Show result banner
    const resultEl = document.getElementById("quiz-result");
    resultEl.classList.add("quiz-result--visible");

    if (correctCount === questions.length) {
      resultEl.classList.add("quiz-result--success");
      resultEl.innerHTML = `
        <svg class="quiz-result__icon" aria-hidden="true" width="20" height="20" viewBox="0 0 20 20" fill="none">
          <circle cx="10" cy="10" r="10" fill="#34d399"/>
          <path d="M5.5 10.5l3 3 5.5-6" stroke="#fff" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>
        </svg>
        <div>
          <div class="quiz-result__title">Perfect score! 🎉</div>
          You answered all 3 questions correctly. Excellent knowledge of programming languages!
        </div>`;
    } else {
      resultEl.classList.add("quiz-result--error");
      resultEl.innerHTML = `
        <svg class="quiz-result__icon" aria-hidden="true" width="20" height="20" viewBox="0 0 20 20" fill="none">
          <circle cx="10" cy="10" r="10" fill="#f87171"/>
          <path d="M7 7l6 6M13 7l-6 6" stroke="#fff" stroke-width="1.8" stroke-linecap="round"/>
        </svg>
        <div>
          <div class="quiz-result__title">Score: ${correctCount} / ${questions.length}</div>
          Review the highlighted answers above — green means correct, red means incorrect.
        </div>`;
    }

    // Disable submit button
    document.getElementById("btn-submit").disabled = true;
    document.getElementById("btn-submit").style.opacity = "0.55";
    document.getElementById("btn-submit").style.cursor = "not-allowed";

    resultEl.scrollIntoView({ behavior: "smooth", block: "nearest" });
  }

  document.addEventListener("DOMContentLoaded", function () {
    document
      .getElementById("quiz-form")
      .addEventListener("submit", handleSubmit);
  });
})();
