      number: "Question 2 of 3",
      text: "Which of the following languages were originally designed for web front-end development?",
      help: null,
      options: [
        { value: "javascript", label: "JavaScript" },
        { value: "css",        label: "CSS" },
        { value: "go",         label: "Go" },
        { value: "coffeescript", label: "CoffeeScript" },
      ],
      correctAnswers: ["javascript", "css", "coffeescript"],
    },
    {
      id: "q3",
      number: "Question 3 of 3",
      text: "Which languages support first-class functions (functions as values)?",
      help: null,
      options: [
        { value: "haskell",    label: "Haskell" },
        { value: "javascript", label: "JavaScript" },
        { value: "c",          label: "C (ANSI C89)" },
        { value: "python",     label: "Python" },
      ],
      correctAnswers: ["haskell", "javascript", "python"],
    },
  ];

  function getChecked(questionId) {
    return Array.from(
      document.querySelectorAll(`input[name="${questionId}"]:checked`)
    ).map((el) => el.value);
  }

  function arraysMatch(a, b) {
    return a.length === b.length && [...a].sort().join() === [...b].sort().join();
  }

  function handleSubmit(e) {
    e.preventDefault();

    const form = document.getElementById("quiz-form");
    form.classList.add("quiz-submitted");

