      if (isFullyCorrect) correctCount++;

      selected.forEach((val) => {
        const input = document.querySelector(
          `input[name="${q.id}"][value="${val}"]`
        );
        if (!input) return;
        const wrapper = input.closest(".checkbox-option");
        if (q.correctAnswers.includes(val)) {
          wrapper.classList.add("checkbox-option--correct");
        } else {
          wrapper.classList.add("checkbox-option--wrong");
        }
      });

      // Update progress segment colour
      const segment = document.getElementById(`progress-${q.id}`);
      if (segment) {
        segment.style.background = isFullyCorrect ? "#34d399" : "#f87171";
      }
    });

