        <div>
          <div class="quiz-result__title">Perfect score! 🎉</div>
          You answered all 3 questions correctly. Excellent knowledge of programming languages!
        </div>`;
    } else {
      resultEl.classList.add("quiz-result--error");
      resultEl.innerHTML = `
        <svg class="quiz-result__icon" aria-hidden="true" width="20" height="20" viewBox="0 0 20 20" fill="none">
          <circle cx="10" cy="10" r="10" fill="#f87171"/>
          <path d="M7 7l6 6M13 7l-6 6" stroke="#fff" stroke-width="1.8" stroke-linecap="round"/>
        </svg>
        <div>
          <div class="quiz-result__title">Score: ${correctCount} / ${questions.length}</div>
          Review the highlighted answers above — green means correct, red means incorrect.
        </div>`;
    }

    // Disable submit button
    document.getElementById("btn-submit").disabled = true;
    document.getElementById("btn-submit").style.opacity = "0.55";
    document.getElementById("btn-submit").style.cursor = "not-allowed";

    resultEl.scrollIntoView({ behavior: "smooth", block: "nearest" });
  }

  document.addEventListener("DOMContentLoaded", function () {
    document
      .getElementById("quiz-form")
      .addEventListener("submit", handleSubmit);
  });
})();

