+*, *::before, *::after {
+  box-sizing: border-box;
+  margin: 0;
+  padding: 0;
+}
+
+:root {
+  --color-bg: #f5f6fa;
+  --color-surface: #ffffff;
+  --color-border: #e2e5ef;
+  --color-border-focus: #5b6af0;
+  --color-primary: #5b6af0;
+  --color-primary-hover: #4757e8;
+  --color-primary-active: #3647d6;
+  --color-text: #1a1d2e;
+  --color-text-secondary: #6b7280;
+  --color-help: #6b7280;
+  --color-check-bg: #5b6af0;
+  --color-check-border: #c9cedf;
+  --color-success-bg: #edfdf4;
+  --color-success-border: #34d399;
